INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R1_XOR_SOURCE_ADVANTAGE','AUDIT_CONFIRMED','R1 and R153 exact GF2 source routing solve 26/50 historical attempts; Kissat solves 0/50 on same cohort; not a universal solver advantage.','ultimate_r1_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42344094697','Historical cohort was selected from prior R153/R195 work, not globally blind.','Replicate against source-SHA-disjoint original industry mixed formulas.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R1_NO_NEW_R153_GAIN','AUDIT_CONFIRMED','R1 30/90 solved and PAR2 3621.517500; R153 30/90 and PAR2 3621.489201; R1 does not beat R153 globally in this sample.','ultimate_r1_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42344094697','R1 vs Kissat advantage is inherited from R153-specialized path.','Retain source-router only when source structure warrants.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R1_R197_ZERO_SOLVES','AUDIT_CONFIRMED','R1, R153, Kissat and CaDiCaL each solve 0/16 official R197 trial attempts.','ultimate_r1_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42344094697','45-second cap prevents finite time-speedup claims.','Add longer and blinded original hard-mixed instances.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R2_CLEAN_BEATS_R153_ON_THIS_SET','AUDIT_CONFIRMED','R2 Clean 18/40 solved, PAR2 1170.721950 vs R153 14/40, PAR2 1383.061857; new-to-R1 14/24 vs 10/24.','ultimate_r2_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42346485260','This identifies CDCL fallback and configuration benefit, NOT GF2 bridge causality.','Ablate native CDCL version/settings using the same original CNF and frozen binaries.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R2_CERTIFIED_REASONS_NO_NET_WIN','AUDIT_CONFIRMED','R2 Live delivers 40 native certified reason clauses on development, 0 on new-to-R1; Live PAR2 1176.449248 > Clean 1170.721950.','ultimate_r2_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42346485260','Delivered reasons are a communication event, not proof of search acceleration; native UNSAT no independent LRAT.','Counterfactual trace where each certified reason changes UP/conflicts before CDCL would derive it.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R2_PREP_COST_REGRESSION','AUDIT_CONFIRMED','Expensive GF2 certification on a quick SAT case consumed approximately 2.8s before veto; bounded preparation lowers per-case wall time but must be amortized.','ultimate_r2_prebudget_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42347804147','Prebudget re-run Clean and Live each solve only 16/40 vs original 18/40; timing perturbations may move near-cap cases.','Same-machine repeated, pinned seeds plus paired confidence intervals; report cap-edge instability.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('SHADOW_NOT_REAL_GAUSS_ABLATION','AUDIT_CONFIRMED','R2 Shadow performs full certified GF2 preparation then runs clean native CDCL; it does not execute live GF2 shadow scans.','ultimate_r2_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42346485260','Cannot attribute Live-Shadow delta to pure propagation cost alone.','Implement real runtime shadow propagator with identical row-activation behavior and no reasons delivered.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('T_RESIDUAL_FRONTIER_HYPOTHESIS','HYPOTHESIS','Useful GF2->CDCL bridge events should be contingent on trail-induced XOR units/conflicts that touch residual CNF high-impact variables before clean UP reaches them.','ultimate_r2_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42346485260','A necessary opportunity heuristic, not a sufficient condition for globally faster SAT solving.','T: compare clean, certified original-source frontier, shadow, derived-row frontier on source-disjoint blind CNFs.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('T_PROOF_OBLIGATION','HYPOTHESIS','For certified row XOR(v1..vk)=b, CDCL partial assignment with exactly one unknown entails one literal and a sound reason clause formed from negated current assignments plus the forced literal.','ultimate_r2_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42346485260','Requires proof that each imported row follows from unchanged source CNF; reasons must be complete and trail-consistent.','Independent replay plus SAT witnesses, native UNSAT machine-checkable LRAT/FRAT, cross-seed stress.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
