INSERT INTO build_status (version,branch,status,last_evidence_url,notes) VALUES ('Neural R5','experiment/drnas-neural-r5-utility-gate-20261107','AUDIT_PASS_NOT_BLIND','https://github.com/Frane12/AndroidGameTest/actions/runs/42338136053','40 sources x 2 reps x 5 arms. Trained on 34 source CNFs / 68 training rewards, 80 epochs. R5 neural 66/80 versus clean 66/80; all 80 neural tests global_no_positive_fast_abstain before model inference; no real alternative activations. No independent native UNSAT LRAT.') ON CONFLICT(version) DO UPDATE SET branch=excluded.branch,status=excluded.status,last_evidence_url=excluded.last_evidence_url,notes=excluded.notes;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R1_SPECIALIZATION_NOT_GENERAL_PROOF','AUDIT_CONFIRMED','Ultimate R1 30/90 solved vs Kissat 4/90; historical GF2 26/50, official R195 4/24 both R1 and Kissat, official R197 0/16 all; R1 and R153 each solve 30/90.','ultimate_r1_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42344094697','Non-blind cohort with historical source reuse; missing native UNSAT independent LRAT.','Independent unseen source-disjoint mixed SAT 2026 holdout with certified SAT models and UNSAT LRAT/FRAT.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R2X_SAME_PREPBUDGET_CODE','AUDIT_CONFIRMED','R2x and R2 PrepBudget have the same fallback Git blob e21224c76200e2992fab9a9589554bcbc575e358 and same benchmark harness; R2x workflow reuses native binary and original manifest.','ultimate_r2x_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42348940571','Across-run minor timing differences are not algorithmic gains.','Test a source-changing candidate against exact frozen clean in the same run.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R2X_LIVE_CLEAN_REGRESSION','AUDIT_CONFIRMED','R2x clean 18/40 PAR2 1166.599241; live 18/40 PAR2 1169.270087; live loses 2.670846 s, paired 1 win / 11 losses / 28 ties.','ultimate_r2x_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42348940571','PAR2 includes timeouts; 12 source-disjoint only relative to R1, no global blind.','Measure certified residual unit consumption before UP and run real shadow vs clean/live with full costs.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R2X_NATIVE_TELEMETRY_CENSORED','AUDIT_LIMITED','Six R2x live-eligible cases (three SHA originals twice) all TIMEOUT; native_mode=null and native_reasons=null, derived_rows=200 over 40 live trials but zero confirmed delivered reasons.','ultimate_r2x_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42348940571','Missing native final-result telemetry on timeouts does not prove solver never activated.','Add live streaming counters and watchdog-safe event checkpoints, compare proof-checked causal UP/learning.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R4F_NO_NEW_SOLVES','AUDIT_CONFIRMED','R4f and R4e both solve 584/616 with identical 176 2SAT, 48 GF2 and 392 clean route counts; R4f PAR2 128.977387 > R4e 128.874675 despite lower gate time 0.055312 vs 0.178626 seconds.','new_horizon_r4f_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42341425816','Reused and generated microinstances; microsecond timing noise; no external blind generalization.','Repeat on independently sourced original CNFs with isolated gate timing and paired repeats.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('NEURAL_R5_NO_MODEL_EXPOSURE','AUDIT_CONFIRMED','Neural R5 80/80 test trials returned global_no_positive_fast_abstain before neural prediction; zero alternate activations; solved 66/80 and PAR2 283.370511 vs clean 66/80 PAR2 283.376300.','neural_r5_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42338136053','Cannot estimate predictive quality of neural model because early training-reward gate blocked model inference.','Collect positive source-disjoint training rewards via offline forced-arm causal experiments, freeze utility gate, evaluate model on truly untouched holdout.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO benchmark_cohorts (cohort_id,version,cohort_type,github_run_id,original_formulas,total_attempts,audit_status,source_url,notes) VALUES ('ultimate_r2t_20261107','Ultimate R2T Portfolio','same_frozen_original_R2_20_source_development_NOT_BLIND',42350937691,20,200,'ULTIMATE_R2_SOURCE_PAIRED_AUDIT_PASS_NOT_GLOBAL_BLIND','https://github.com/Frane12/AndroidGameTest/actions/runs/42350937691','5 arms, 20 previously used original frozen R2 CNFs, 2 repeats, NOT independent blind. Portfolio is structural Horn/binary selector; no delivered GF2 reasons.') ON CONFLICT(cohort_id) DO UPDATE SET version=excluded.version,cohort_type=excluded.cohort_type,github_run_id=excluded.github_run_id,original_formulas=excluded.original_formulas,total_attempts=excluded.total_attempts,audit_status=excluded.audit_status,source_url=excluded.source_url,notes=excluded.notes;
