INSERT INTO build_status (version,branch,status,last_evidence_url,notes) VALUES ('Ultimate T2 phase2','experiment/drnas-ultimate-t2-causal-isolation-20261107','ULTIMATE_T2_PHASE2_AUDIT_PASS_NONBLIND','https://github.com/Frane12/AndroidGameTest/actions/runs/42352823564','10 arms, 20 previously used original R2 CNFs, 2 repeats, 5/5 shard audit PASS; SAT witnesses checked original SHA. Native UNSAT has no independent LRAT; terminal telemetry on some TIMEOUTs missing.') ON CONFLICT(version) DO UPDATE SET branch=excluded.branch,status=excluded.status,last_evidence_url=excluded.last_evidence_url,notes=excluded.notes;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('T2_ALL40_CLEAN_VS_R153','AUDIT_CONFIRMED','Within T2 400-attempt factorial T clean solved 16/40 PAR2 1240.368493 versus R153 14/40 PAR2 1390.198323; 149.829830 s paired gain, nonblind 20 original frozen CNFs.','ultimate_t2_phase2_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42352823564','Only original R2 reused development corpus; does not establish external generalization or GF2 causal benefit.','Check source-disjoint TA and independent multi-seed, matched cap runner.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('T2_NO_DERIVED_CAUSAL_GAIN','AUDIT_CONFIRMED','T2 derived incremental solved 16/40 PAR2 1242.885956 versus Clean 16/40 PAR2 1240.368493: -2.517463 s paired gain. Derived rows -2.559577 s; derived units -2.554489 s, no new solved.','ultimate_t2_phase2_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42352823564','Progress 40 completed reasons and 108 proposals are not proof that CDCL consumed any reason or that these changed outcomes.','Add actual reason-consumed counters and causal ablation; cost-gate before frontier work.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('T2_DEVELOPMENT_ONLY_REASON_ACTIVITY','AUDIT_CONFIRMED','T2 derived incremental has 108 proposals and 40 reason-completions in progress telemetry solely in development; new_to_r1 has 0 such completions and T2 derived does not improve solved.','ultimate_t2_phase2_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42352823564','Terminal native result missing in 6 eligible trials; progress and consumption differ; no independent native UNSAT LRAT.','Use watchdog-safe event telemetry, verify proof chain and trial-level CDCL reason use.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('T2_FRONTIER_UPDATE_OVERHEAD','AUDIT_CONFIRMED','T2 derived incremental generated 106555192 frontier update events across 40 attempts, without a paired PAR2 benefit over Clean.','ultimate_t2_phase2_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42352823564','An event count is not CPU seconds and some timeout runs are censored; cannot attribute whole slowdown to frontier.','Profile event cost and replay cost-gated sparse update policy in TD causal test.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('T2_STREAMING_VETO_INCONCLUSIVE','AUDIT_LIMITED','The bounded XOR probe yields no_complete_xor_in_bounded_stream with incomplete_scan=true for multiple original CNFs; absent selected XOR rows can reflect incomplete group retention.','ultimate_t2_phase2_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42352823564','Does not establish that any missed complete XOR exists or that finding one would speed up CDCL.','TD exact partitioned full-CNF scan diagnostic versus bounded streaming on frozen originals with independent source cert replay.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('T1_T2_NONPAIRED_INSTABILITY','AUDIT_LIMITED','Across two separate CI runs on the same frozen 20 originals, T1 Clean solved 18/40 PAR2 1153.728945, T2 Clean solved 16/40 PAR2 1240.368493.','ultimate_t2_phase2_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42352823564','Different CI executions are NOT paired; verify native SHA, fallback code and runner timing before inferring algorithmic change.','Same-job side-by-side binaries with pinned hashes; pair original SHA and caps, repeat independent seeds.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R2T_PORTFOLIO_DEVELOPMENT_GAIN','AUDIT_CONFIRMED','R2T portfolio 18/40 PAR2 1155.276228 versus R2 Clean 18/40 PAR2 1168.671126, paired gain 13.394898 s, 4 wins/7 losses/29 ties; zero confirmed GF2 reasons.','ultimate_r2t_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42350937691','Structural selector was designed on these originals; result NOT blind and not evidence of general-purpose benefit.','Complete TA 30 source-disjoint SAT2026 original CNFs and audit unchanged source SHA, SAT models and paired PAR2.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('T2_LRAT_NOT_AVAILABLE','AUDIT_LIMITED','T2 final audit verifies original SHA and SAT witnesses, but native UNSAT returns do not include independent LRAT/FRAT proof; terminal telemetry missing on eligible timeout runs.','ultimate_t2_phase2_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42352823564','SAT witness correctness and expected verdict agreement are not equivalent to independent UNSAT proof.','Add machine-checkable UNSAT proofs, event checkpoints for killed processes and verifier before scientific claim.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
