INSERT INTO build_status (version,branch,status,last_evidence_url,notes) VALUES ('TD exact-bucket source diagnostic','experiment/drnas-td-exact-bucket-probe-20261107','TD_BUCKETED_DIAGNOSTIC_AUDIT_PASS','https://github.com/Frane12/AndroidGameTest/actions/runs/42356263207','20/20 original frozen SHA verified, 8 source cases with exact XOR groups, no newly detected sources, 11912 distinct source XOR patterns in those 8 cases; 0 incomplete. Streaming total 0.402115 s vs exact bucket 6.599585 s. No solver PAR2 measured, no independent UNSAT LRAT.') ON CONFLICT(version) DO UPDATE SET branch=excluded.branch,status=excluded.status,last_evidence_url=excluded.last_evidence_url,notes=excluded.notes;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('TD_EXACT_BUCKET_ORIGINAL20_NEGATIVE','AUDIT_CONFIRMED','TD exact bucket source scan on 20 original SHA-confirmed R2 CNFs found XOR patterns in the SAME 8 cases detected by T2 streaming (old_hits=8, new_source_cases=0); 11912 groups total, complete in 20/20, 0 overflow.',NULL,'https://github.com/Frane12/AndroidGameTest/actions/runs/42356263207','Exact scanner only identifies complete width 2-6 source clauses. It does not rule out longer/implicit XOR and counts patterns, not productive CDCL propagations.','Do NOT deploy 8-pass exact scanning in production; prioritize causal use of certified GF2 reasons or low-cost structural gating.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('TD_EXACT_BUCKET_TIME_COST','AUDIT_CONFIRMED','TD 20-source detector-only run measured 6.599585 s exact partitioned scan vs 0.402115 s original streaming scan, roughly 16.4x more scan time; no new positive source case.',NULL,'https://github.com/Frane12/AndroidGameTest/actions/runs/42356263207','One CI environment, different scan workloads; not a paired SAT solver wall-time or PAR2 result.','Only revisit bucket scan if external original source-disjoint evidence shows late complete XOR and net end-to-end PAR2 gains.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('TD_SYNTHETIC_INTERLEAVED_RECALL','AUDIT_LIMITED','Interleaved synthetic XOR parity encoding: old streaming missed it; exact bucket scan detected 1 complete XOR group; negative control returned 0.',NULL,'https://github.com/Frane12/AndroidGameTest/actions/runs/42356263207','Planted synthetic test establishes feature recall but not improvement in real SAT solve time or generalization.','Keep as regression selftest, do not promote as solver speedup evidence.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('TD_NEXT_REASON_CONSUMPTION_COST_GATE','HYPOTHESIS','T2 emitted 108 proposed and 40 completed derived GF2 reason events but no demonstrated improvement relative to Clean; 106555192 frontier update events make sparse high-impact reason consumption a more promising target than exhaustive extra source scanning.','ultimate_t2_phase2_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42356263207','Completed reason telemetry is not verified CDCL consumption; this remains an untested causal gate idea.','Next TD build: Clean vs shadow vs identical certified derived path with low-cost threshold of residual CNF overlap and telemetry on actual reason consumption, CPU time, paired solved/PAR2; ablate gate and freeze source SHA/seeds.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('T1_T2_REPEAT_RUN_CAUSALITY_GAP','AUDIT_LIMITED','T1 T Clean 18/40 PAR2 1153.728945 and T2 T Clean 16/40 PAR2 1240.368493 across separate CI runs despite same original source manifest.','ultimate_t2_phase2_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42356263207','Across-run timings and solved differences cannot be causally assigned to T2 code or GF2 methods; timeout censoring and execution order need investigation.','Run pinned T1-vs-T2 native Clean in the SAME GitHub job on identical original CNFs, paired seeds and caps, checksum binaries and report per-case status divergences.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO benchmark_cohorts (cohort_id,version,cohort_type,github_run_id,original_formulas,total_attempts,audit_status,source_url,notes) VALUES ('td_lazy_source_440_20261107','TD Lazy Source 11-arm','same_frozen_original_R2_20_source_development_NOT_BLIND',42356438634,20,440,'ULTIMATE_TD_LAZY_SOURCE_AUDIT_PASS_NONBLIND','https://github.com/Frane12/AndroidGameTest/actions/runs/42356438634','20 frozen original R2 SHA manifest 2e6169009e985555e43e81d9b534f3bb307cef93963329694ef42459bef3c2e2, 11 arms x 40, 2 reps, 5/5 shards. Native UNSAT has no independent LRAT; terminal missing 8 for source eligible timeouts. No delivered source reasons.') ON CONFLICT(cohort_id) DO UPDATE SET version=excluded.version,cohort_type=excluded.cohort_type,github_run_id=excluded.github_run_id,original_formulas=excluded.original_formulas,total_attempts=excluded.total_attempts,audit_status=excluded.audit_status,source_url=excluded.source_url,notes=excluded.notes;
