INSERT INTO build_status (version,branch,status,last_evidence_url,notes) VALUES ('TD Lazy Source 440','experiment/drnas-td-lazy-source-20261107','ULTIMATE_TD_LAZY_SOURCE_AUDIT_PASS_NONBLIND','https://github.com/Frane12/AndroidGameTest/actions/runs/42356438634','SUCCESS 5/5 shards, 440/440; td_lazy_source 16/40 PAR2 1235.895448 vs t_source 16/40 PAR2 1235.887583 (-0.007865s) vs t_clean 16/40 PAR2 1237.336485 (+1.441037s). 0 source delivered reasons; 0 lazy frontier updates vs 72,868,484 eager events. No causal source speedup.') ON CONFLICT(version) DO UPDATE SET branch=excluded.branch,status=excluded.status,last_evidence_url=excluded.last_evidence_url,notes=excluded.notes;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('TD_LAZY_440_ZERO_SOURCE_GAIN','AUDIT_CONFIRMED','TD lazy source 440 paired: td_lazy_source 16/40 SAT12 UNSAT4 PAR2 1235.895448, t_source 16/40 PAR2 1235.887583; paired gain -0.007865s, 1 win/1 loss/38 ties. Clean 16/40 PAR2 1237.336485; lazy gain 1.441037s but no source-specific advantage vs t_source or shadow.','td_lazy_source_440_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42356438634','The identical original frozen R2 development CNFs are not blind. Subsecond fluctuations and no delivered source reasons mean no proof of GF2 causal benefit.','Reject lazy as a speedup; verify reason consumption and matched new source-disjoint families before changing production.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('TD_LAZY_EVENT_REMOVAL_NOT_SPEEDUP','AUDIT_CONFIRMED','Lazy source removes all 72,868,484 eager frontier update events of t_source, while 16/40 solved and PAR2 1235.895448 vs source 1235.887583.','td_lazy_source_440_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42356438634','Event counts do not equal CPU time, and terminal_missing=8 means timeout-native telemetry is incomplete.','Instrument CPU ns and per-trail updates in same process, and run ablation on eligible source formulas with delivered reason callbacks.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('TD_LAZY_DERIVED_STILL_NO_CAUSAL_GAIN','AUDIT_CONFIRMED','Derived incremental 16/40 PAR2 1239.927254 vs Clean 16/40 1237.336485, 108 proposals and 40 completed reasons all in development; new_to_r1 has zero proposals/reasons.','td_lazy_source_440_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42356438634','Completed reasons are not independently verified CDCL consumed reason callbacks, no independent native UNSAT LRAT.','Cost-gate certification by cheap residual overlap; compare Clean/Shadow/Source and actual reason-consumed counters.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('TD_LAZY_T1_T2_REPRO_GAP','AUDIT_LIMITED','T Clean across separate T1, T2, TD lazy runs had 18/40 PAR2 1153.728945, 16/40 PAR2 1240.368493, 16/40 PAR2 1237.336485.','td_lazy_source_440_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42356438634','Different run binaries/environments/runner scheduling are not same-job matched; source SHA same but causal inference invalid.','Same-job pinned T1/T2 clean binary side-by-side reproduction with 2+ seeds and per-case status.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
